const signal = AbortSignal.any([userController.signal, AbortSignal.timeout(500)]);
try {
  const res = await fetch(url, { signal });
  return await res.json();
} catch (err) {
  if (err.name === 'TimeoutError') throw new DependencyTimeout();  // deadline
  if (err.name === 'AbortError') throw err;                       // caller cancelled
  throw err;
}

