function withTimeout(promise, ms) {
  let t;
  const timer = new Promise((_, reject) => {
    t = setTimeout(() => reject(new TimeoutError()), ms);
  });
  return Promise.race([promise, timer]).finally(() => clearTimeout(t));
}
